# Hypothesis: for each pair, identify 'template' objects (multi-cell components, possibly multi-color) 
# and single-pixel seeds; rule: replicate each template with its rare color aligned onto each seed of that color.
def objects(g):
    seen=set(); res=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and (i,j) not in seen:
                stack=[(i,j)]; c=[]; seen.add((i,j))
                while stack:
                    y,x=stack.pop(); c.append((y,x))
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(y+di,x+dj)
                        if 0<=n[0]<len(g) and 0<=n[1]<len(g[0]) and g[n[0]][n[1]] and n not in seen:
                            seen.add(n); stack.append(n)
                ys=[p[0] for p in c]; xs=[p[1] for p in c]
                cols={g[y][x] for y,x in c}
                top=(min(ys),min(xs))
                res.append({'cells':sorted(c),'top':top,'colors':cols,'size':len(c)})
    return res
def f(g):
    from collections import defaultdict
    objs=objects(g)
    singles=[o for o in objs if o['size']==1]
    templates=[o for o in objs if o['size']>1]
    out=[row[:] for row in g]
    # rare color per template = least common color within it
    def rare(o):
        cnt=Counter(o['colors']); return min(cnt,key=lambda c:(cnt[c],c))
    for T in templates:
        rc=rare(T)
        for S in singles:
            if list(S['colors'])[0]!=rc: continue
            # find where the rare color cell is in the template
            pos=[(y,x) for y,x in T['cells'] if g[y][x]==rc]
            if len(pos)!=1: continue
            py,px=pos[0]
            ty,tx=T['top']
            delta=(S['top'][0]-py,S['top'][1]-px)
            Hh=len(out); Ww=len(out[0])
            pat={(y,x):out[y][x] for y,x in T['cells']}
            oy,ox=ty+delta[0],tx+delta[1]
            for (y,x),(v) in pat.items():
                ny,nx=y+oy,x+ox
                if 0<=ny<Hh and 0<=nx<Ww: out[ny][nx]=v
    return out
